local Players=game:GetService("Players") local RunService=game:GetService("RunService") local UIS=game:GetService("UserInputService") local TS=game:GetService("TweenService") local Camera=workspace.CurrentCamera local LP=Players.LocalPlayer local Unlocked=false local Key="khalil" local S={ESP=false,Tracers=false,Boxes=false,Names=false,Dist=false,Aim=false,Aura=false,AimBody=false,FOV=150,Smooth=0.5,Wall=true,Fly=false,God=true,Anti=true,SpeedHack=false,RGB=false,TColor=Color3.fromRGB(0,255,180),BColor=Color3.fromRGB(255,180,0)} local EO,TL,BO,IT,HB,TT={},{},{},{},{},{} local FOVC=nil local fBV,fBG,fC local SelP=nil local SG=Instance.new("ScreenGui") SG.Name="SndGui" SG.Parent=game.CoreGui local CS=Instance.new("Sound") CS.SoundId="rbxassetid://8750226842" CS.Volume=0.5 CS.Parent=SG local AS=Instance.new("Sound") AS.SoundId="rbxassetid://5766958637" AS.Volume=0.5 AS.Parent=SG local function snd() if CS then CS:Play() end if AS then AS:Play() end end pcall(function() local ok=LP.Kick LP.Kick=function(self,m) if m and (string.find(string.lower(m),"detector") or string.find(string.lower(m),"exploit")) then return end return ok(self,m) end end) RunService.Heartbeat:Connect(function() if not S.Anti then return end local c=LP.Character if c then for _,p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") and p.Velocity.Magnitude>150 then p.Velocity=Vector3.zero p.RotVelocity=Vector3.zero end end end end) RunService.Heartbeat:Connect(function() if Unlocked then UIS.MouseBehavior=Enum.MouseBehavior.Default end end) local rgbFrame=Instance.new("Frame",SG) rgbFrame.Size=UDim2.new(1,0,1,0) rgbFrame.BorderSizePixel=0 rgbFrame.ZIndex=0 rgbFrame.BackgroundTransparency=0.5 rgbFrame.Visible=false RunService.RenderStepped:Connect(function() rgbFrame.Visible=S.RGB if S.RGB then rgbFrame.BackgroundColor3=Color3.fromHSV((tick()*0.5)%1,1,1) end end) local function applyESP(p) if p==LP or not p.Character then return end if EO[p] then EO[p]:Destroy() end local h=Instance.new("Highlight") h.FillColor=Color3.fromRGB(255,0,100) h.FillTransparency=0.5 h.OutlineColor=Color3.fromRGB(0,255,255) h.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop h.Adornee=p.Character h.Enabled=S.ESP h.Parent=p.Character EO[p]=h end local function mkTr(p) if p==LP then return end if not TL[p] then local l=Drawing.new("Line") l.Visible=false l.Thickness=2 TL[p]=l end if not BO[p] then local b={} for i=1,4 do local l=Drawing.new("Line") l.Visible=false l.Thickness=1.5 b[i]=l end BO[p]=b end if not IT[p] then local t=Drawing.new("Text") t.Visible=false t.Size=16 t.Center=true t.Outline=true IT[p]=t end if not TT[p] then local t=Drawing.new("Text") t.Visible=false t.Size=15 t.Center=true t.Outline=true t.Text="Khalil Hex" TT[p]=t end if not HB[p] then local bg=Drawing.new("Line") bg.Visible=false bg.Thickness=4 bg.Color=Color3.fromRGB(0,0,0) local fg=Drawing.new("Line") fg.Visible=false fg.Thickness=4 fg.Color=Color3.fromRGB(0,255,120) HB[p]={bg=bg,fg=fg} end end FOVC=Drawing.new("Circle") FOVC.Visible=false FOVC.Thickness=2 FOVC.NumSides=60 FOVC.Color=Color3.fromRGB(0,180,255) FOVC.Transparency=0.8 FOVC.Filled=false RunService.RenderStepped:Connect(function() FOVC.Position=Vector2.new(Camera.ViewportSize.X/2,Camera.ViewportSize.Y/2) FOVC.Radius=S.FOV FOVC.Visible=S.Aim local myH=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") for p,l in pairs(TL) do local c=p.Character local hd=c and c:FindFirstChild("Head") local hu=c and c:FindFirstChild("Humanoid") local hb=HB[p] if not hd or not hu then l.Visible=false if IT[p] then IT[p].Visible=false end if TT[p] then TT[p].Visible=false end if BO[p] then for i=1,4 do BO[p][i].Visible=false end end if hb then hb.bg.Visible=false hb.fg.Visible=false end else local hp=hd.Position+Vector3.new(0,1.5,0) local pos,on=Camera:WorldToViewportPoint(hp) if S.Tracers and on then l.From=Vector2.new(Camera.ViewportSize.X/2,0) l.To=Vector2.new(pos.X,pos.Y) l.Color=S.TColor l.Visible=true if TT[p] then TT[p].Text="Khalil Hex" TT[p].Position=Vector2.new(l.From.X, l.From.Y + 15) TT[p].Color=S.TColor TT[p].Visible=true end else l.Visible=false if TT[p] then TT[p].Visible=false end end local rt=c:FindFirstChild("HumanoidRootPart") if S.Boxes and on and rt then local hp2,ho=Camera:WorldToViewportPoint(hd.Position+Vector3.new(0,0.5,0)) local fp,fo=Camera:WorldToViewportPoint(rt.Position-Vector3.new(0,3,0)) if ho and fo then local hh=math.abs(fp.Y-hp2.Y) local ww=hh/2 local tl,tr=Vector2.new(hp2.X-ww/2,hp2.Y),Vector2.new(hp2.X+ww/2,hp2.Y) local bl,br=Vector2.new(hp2.X-ww/2,fp.Y),Vector2.new(hp2.X+ww/2,fp.Y) local bx=BO[p] bx[1].From=tl bx[1].To=tr bx[2].From=tr bx[2].To=br bx[3].From=br bx[3].To=bl bx[4].From=bl bx[4].To=tl for i=1,4 do bx[i].Color=S.BColor bx[i].Visible=true end else for i=1,4 do BO[p][i].Visible=false end end else if BO[p] then for i=1,4 do BO[p][i].Visible=false end end end if (S.Names or S.Dist) and on and myH then local d=math.floor((myH.Position-hd.Position).Magnitude) local ts="" if S.Names then ts=p.Name end if S.Dist then ts=ts.." ["..d.."m]" end local tg=IT[p] tg.Text=ts tg.Position=Vector2.new(pos.X,pos.Y-22) tg.Color=Color3.fromRGB(255,255,255) tg.Visible=true else if IT[p] then IT[p].Visible=false end end end end end) local function getT() local ce=Vector2.new(Camera.ViewportSize.X/2,Camera.ViewportSize.Y/2) local cl,sh=nil,S.FOV local rp=RaycastParams.new() rp.FilterType=Enum.RaycastFilterType.Exclude rp.FilterDescendantsInstances={LP.Character,Camera} for _,p in ipairs(Players:GetPlayers()) do if p==LP or not p.Character then continue end local tp=p.Character:FindFirstChild("Head") if S.AimBody then tp=p.Character:FindFirstChild("UpperTorso") or p.Character:FindFirstChild("Torso") end if not tp then continue end local po,on=Camera:WorldToViewportPoint(tp.Position) if not on then continue end local d=(Vector2.new(po.X,po.Y)-ce).Magnitude if d>=sh then continue end if S.Wall then local r=workspace:Raycast(Camera.CFrame.Position,tp.Position-Camera.CFrame.Position,rp) if r and not r.Instance:IsDescendantOf(p.Character) then continue end end sh=d cl=tp end return cl end RunService.RenderStepped:Connect(function() if not S.Aim then return end local t=getT() if t then Camera.CFrame=Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.Position,t.Position),S.Smooth) end end) local function tFly(st) S.Fly=st local c=LP.Character local h=c and c:FindFirstChild("HumanoidRootPart") local hu=c and c:FindFirstChild("Humanoid") if st and h and hu then hu.PlatformStand=true fBV=Instance.new("BodyVelocity") fBV.MaxForce=Vector3.new(9e9,9e9,9e9) fBV.Velocity=Vector3.zero fBV.Parent=h fBG=Instance.new("BodyGyro") fBG.MaxTorque=Vector3.new(9e9,9e9,9e9) fBG.P=1000 fBG.Parent=h fC=RunService.RenderStepped:Connect(function() if not S.Fly or not c or not c.Parent then return end local d=Vector3.zero if UIS:IsKeyDown(Enum.KeyCode.W) then d=d+Camera.CFrame.LookVector end if UIS:IsKeyDown(Enum.KeyCode.S) then d=d-Camera.CFrame.LookVector end if UIS:IsKeyDown(Enum.KeyCode.A) then d=d-Camera.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.D) then d=d+Camera.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.Space) then d=d+Vector3.new(0,1,0) end if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then d=d-Vector3.new(0,1,0) end fBV.Velocity=d.Magnitude>0 and d.Unit*60 or Vector3.zero fBG.CFrame=Camera.CFrame end) else if fC then fC:Disconnect() end if fBV then fBV:Destroy() end if fBG then fBG:Destroy() end if hu then hu.PlatformStand=false end end end RunService.Heartbeat:Connect(function() if not S.God then return end local hu=LP.Character and LP.Character:FindFirstChild("Humanoid") if hu and hu.Health<hu.MaxHealth then hu.Health=hu.MaxHealth end end) RunService.Heartbeat:Connect(function() local hu=LP.Character and LP.Character:FindFirstChild("Humanoid") if hu then hu.WalkSpeed = S.SpeedHack and 120 or 16 end end) for _,p in ipairs(Players:GetPlayers()) do if p~=LP then applyESP(p) mkTr(p) end end Players.PlayerAdded:Connect(function(p) p.CharacterAdded:Connect(function(c) c:WaitForChild("Head",5) task.wait(0.2) applyESP(p) mkTr(p) end) end)
